mapper.select:
SELECT id FROM manga_generation_media_object
WHERE status IN ('PENDING', 'RETIRING', 'DELETED') AND next_attempt_at <= #{now}
  AND (claim_until IS NULL OR claim_until <= #{now})
ORDER BY next_attempt_at, id LIMIT #{limit}

mapper.update:
UPDATE manga_generation_media_object SET status = CASE WHEN #{deleted} THEN 'DELETED' ELSE 'RETIRING' END,
    claim_owner = NULL, claim_until = NULL, next_attempt_at = #{next}, updated_by = #{actor}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND status = 'RETIRING' AND claim_owner = #{token}
